import requests
from pathlib import Path
from robot.utils.robottypes import is_truthy

import logging

from taf.converters.base.interface import base
from taf.collectors.core.entities.local_executor import LocalExecutor

from .factory import TtiTracerConverterFactory

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ttitracer(base):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self, **kwargs):
        super(ttitracer, self).__init__(**kwargs)
        self._local_executor = self._create_local_executor()

    def install_ttitracer(
            self,
            version,
            install_path="/opt/TtiTracer",
            base_url="https://artifactory-espoo2.int.net.nokia.com/artifactory/mn-cosi-sran-central-public-local/build",
            force=False,
            release=None,
            token=None):

        """
        Install 4G TTI trace decoders (TtiTracer.zip(FDD) and pstools.zip(TDD)) for a SBTS load.

        :param str version:
            SBTS load version
        :param Optional[str] install_path:
            path to install the ttitracer, default is /opt/TtiTracer
        :param Optional[str] base_url:
            base url to retrieve TtiTracer.zip, default is
            `<https://artifactory-espoo2.int.net.nokia.com/artifactory/mn-cosi-sran-central-public-local/build>`_
        :param Optional[str] force:
            if True: Removes existing installation directory before installing ttitracer,
            default is False
        :param Optional[str] release:
            release version of the ttitracer, default is prefix of the version before the first underscore,
            e. g. for version "SBTS00_ENB_9999_220204_000002", release is "SBTS00"
        :param token: token to access the artifactory, default is the content of /etc/token/ca_ute_artifactory_readonly

        """
        if release is None:
            release = version.split("_")[0]

        url_fdd = f'{base_url}/{release}/{version}/{version}_TtiTracer.zip'

        url_tdd = f'{base_url}/{release}/{version}/{version}_pstools.zip'

        token_to_use = token if token else self._get_default_token().decode()

        logger.info(f"Getting 4G ttitrace decoder (FDD) from {url_fdd}")

        self._retrieve_url(url_fdd, "/tmp/ttitracer.zip", token_to_use)

        logger.info(f"Getting 4G ttitrace decoder (FDD) from {url_tdd}")

        self._retrieve_url(url_tdd, "/tmp/pstools.zip", token_to_use)

        sudo_prefix = self._local_executor.sudo_prefix()

        create_install_directory = f'{sudo_prefix}mkdir "{install_path}"'

        remove_install_directory = f'{sudo_prefix}rm -rf "{install_path}"'

        extract_command_fdd = f'{sudo_prefix}unzip /tmp/ttitracer.zip -d "{install_path}"'

        extract_command_tdd = f'{sudo_prefix}unzip /tmp/pstools.zip -d "{install_path}"'

        change_ownership = f'{sudo_prefix}chown -R $(id -u):$(id -g) "{install_path}"'

        remove_tmp_files = "rm -f /tmp/ttitracer.zip /tmp/pstools.zip"

        if is_truthy(force):
            self._local_executor.execute(remove_install_directory)
        self._local_executor.execute(create_install_directory)

        self._local_executor.execute(extract_command_fdd)
        self._local_executor.execute(extract_command_tdd)
        self._local_executor.execute(change_ownership)

        self._local_executor.execute(remove_tmp_files)

        logger.info("4G ttitrace(FDD/TDD) for load %s installed successfully" % version)

    def _create_local_executor(self):
        return LocalExecutor()

    def _retrieve_url(self, url, filename, token):
        headers = {'Authorization': f'Bearer {token}'}

        response = requests.get(url, headers=headers)
        response.raise_for_status()

        self._write_file(filename, response.content)

    def _get_default_token(self):
        return self._read_file('/etc/token/ca_ute_artifactory_readonly').strip()

    def _read_file(self, file_path):
        return Path(file_path).read_bytes()

    def _write_file(self, file_path, content):
        Path(file_path).write_bytes(content)

    def create_ttitracer_converter(
            self,
            name,
            file_path_pattern,
            output_directory=None,
            ttitracer_directory=None,
            options=None,
            sudo_password=None,
            duplex=None
    ):

        """
        Create a converter to convert 4G TtiTrace \\*.dat trace to .txt and .txt.harq using TtiTracer.zip

        :param str name: name of the converter
        :param str file_path_pattern:
            source trace file or name pattern with path to the trace files
        :param Optional[str] output_directory:
            directory where output files should be stored, default same as input path
        :param Optional[str] ttitracer_directory:
            directory where the TtiTracer.zip is installed, default is /opt/TtiTracer
        :param Optional[str] options:
            optional arguments to the ttitracer executable, default empty string
        :param Optional[str] sudo_password:
            password for sudo, default empty string
        :param Optional[str] duplex:
            specify whether running ttitrace for FDD or TDD cells, default "fdd"
            for TDD cells pass "tdd"

        """

        logger.info("Creating Converter with alias name " + name)
        configuration = {"file_path_pattern": file_path_pattern}
        for parameter_name, parameter_value in locals().items():
            if parameter_name in [
                    "output_directory",
                    "ttitracer_directory",
                    "options",
                    "sudo_password",
                    "duplex"]:
                if parameter_value is not None:
                    configuration[parameter_name] = parameter_value

        converter = TtiTracerConverterFactory().create(
            configuration=configuration,
            existing_arguments={})
        self.set_alias(name, converter)
        logger.info(name + " converter created successfully")
